(756916, 81479, 22597, '<td valign="top">Nice idea and beautiful subject, though the image is slightly out of focus...<br/></td>', 'Nice idea and beautiful subject, though the image is slightly out of focus...', '2004-06-09 12:38:59.000000', NULL, 1),
(756917, 82286, 18854, '<td valign="top">Great colors on the sail to contrast with the mountains. Nice placement of the boat on the right side as well to give it room to sail to the left.  I would have flipped the photo horizontally to make the boat go from left to right, just to see if that made the shot feel any different.  Great shot!</td>', 'Great colors on the sail to contrast with the mountains. Nice placement of the boat on the right side as well to give it room to sail to the left.  I would have flipped the photo horizontally to make the boat go from left to right, just to see if that made the shot feel any different.  Great shot!', '2004-06-09 12:39:06.000000', NULL, 1),
(756918, 82414, 22734, '<td valign="top">good concept</td>', 'good concept', '2004-06-09 12:39:25.000000', NULL, 1),
