(756922, 81475, 22734, '<td valign="top">nice shot</td>', 'nice shot', '2004-06-09 12:40:25.000000', NULL, 1),
(756923, 82286, 16126, '<td valign="top">I see a filled sail, so they''re not waiting for wind! Nice picture though, the contrast of the crisp colorful sail with the faded background works very well. Very good composition also. 7</td>', 'I see a filled sail, so they''re not waiting for wind! Nice picture though, the contrast of the crisp colorful sail with the faded background works very well. Very good composition also. 7', '2004-06-09 12:40:32.000000', NULL, 1),
