(757302, 81912, 20115, '<td valign="top">Looks like you had fun with this one.  Who hung up there--is it just the pants and shoes?</td>', 'Looks like you had fun with this one.  Who hung up there--is it just the pants and shoes?', '2004-06-09 15:40:26.000000', NULL, 1),
(757303, 81785, 327, '<td valign="top">Very cool. Hope you tell us what it says. I''m only sorry you didn''t include the mans legs. Nice entry good luck.</td>', 'Very cool. Hope you tell us what it says. I''m only sorry you didn''t include the mans legs. Nice entry good luck.', '2004-06-09 15:40:45.000000', NULL, 1),
(757304, 81706, 327, '<td valign="top">Nice macro. Cool feet!!</td>', 'Nice macro. Cool feet!!', '2004-06-09 15:41:25.000000', NULL, 1),
(757305, 82257, 327, '<td valign="top">I love this shot. Her expression, the light. 9 from me.</td>', 'I love this shot. Her expression, the light. 9 from me.', '2004-06-09 15:41:59.000000', NULL, 1),
(757306, 81737, 20115, '<td valign="top">Very nice.</td>', 'Very nice.', '2004-06-09 15:41:59.000000', NULL, 1),
(757307, 80938, 20115, '<td valign="top">Beautiful room.</td>', 'Beautiful room.', '2004-06-09 15:42:15.000000', NULL, 1),
(757312, 82157, 22478, '<td valign="top">Waiting is clearly communicated.  The colors are good.  There are few distractions.  The pipe stub alternately attracts my curiously while provoking a sense of distraction.</td>', 'Waiting is clearly communicated.  The colors are good.  There are few distractions.  The pipe stub alternately attracts my curiously while provoking a sense of distraction.', '2004-06-09 15:44:31.000000', NULL, 1),
