(757314, 81440, 22478, '<td valign="top">Waiting indeed.  The B/W rendering is effective.  Details above people''s heads are somewhat distracting.</td>', 'Waiting indeed.  The B/W rendering is effective.  Details above people''s heads are somewhat distracting.', '2004-06-09 15:46:02.000000', NULL, 1),
(757316, 81114, 327, '<td valign="top">CHIKEN...chicken? Sounds good either way!</td>', 'CHIKEN...chicken? Sounds good either way!', '2004-06-09 15:46:42.000000', NULL, 1),
