(757320, 81380, 22478, '<td valign="top">Waiting (or too much thereof) clearly communicated.  Great choice of subject, but is oddly truncated by the closer faces on the left.</td>', 'Waiting (or too much thereof) clearly communicated.  Great choice of subject, but is oddly truncated by the closer faces on the left.', '2004-06-09 15:48:59.000000', NULL, 1),
(757321, 81543, 327, '<td valign="top">Needs a bit of focus. Good luck.</td>', 'Needs a bit of focus. Good luck.', '2004-06-09 15:49:41.000000', NULL, 1),
(757324, 82416, 327, '<td valign="top">I think maybe you should of cropped out the top sign.  Your colors are nice.</td>', 'I think maybe you should of cropped out the top sign.  Your colors are nice.', '2004-06-09 15:50:53.000000', NULL, 1),
(757326, 82318, 22478, '<td valign="top">Communicates clearly.  Good framing.  Good color.  Good job.</td>', 'Communicates clearly.  Good framing.  Good color.  Good job.', '2004-06-09 15:52:17.000000', NULL, 1),
(757329, 82142, 327, '<td valign="top">I like your idea. Unique. I would of suggested more light and more focus. Just my thoughts. I think the noise maybe from lack of light. &lt;?&gt;</td>', 'I like your idea. Unique. I would of suggested more light and more focus. Just my thoughts. I think the noise maybe from lack of light. <?>', '2004-06-09 15:54:55.000000', NULL, 1),
(757331, 81380, 327, '<td valign="top">Good candid shot. Poor guy is bored out of his mind!! :) Good entry.</td>', 'Good candid shot. Poor guy is bored out of his mind!! :) Good entry.', '2004-06-09 15:55:27.000000', NULL, 1),
(757333, 81049, 22478, '<td valign="top">Terrific.  A waiting attitude symetrically framed by mirrored waiting attitudes.  The text of the sign is a great counterpoint (as in, "What are they waiting for if no one is allowed to stop?")</td>', 'Terrific.  A waiting attitude symetrically framed by mirrored waiting attitudes.  The text of the sign is a great counterpoint (as in, "What are they waiting for if no one is allowed to stop?")', '2004-06-09 15:57:33.000000', NULL, 1),
