(757971, 81090, 19841, '<td valign="top">The flash seems harsh on her face.  A softer light, from the side, would have seemed more sympathetic.   It is well composed, exposed, and focused.</td>', 'The flash seems harsh on her face.  A softer light, from the side, would have seemed more sympathetic.   It is well composed, exposed, and focused.', '2004-06-09 22:46:43.000000', NULL, 1),
(757973, 82362, 16430, '<td valign="top">Great shot and it''s very interesting that the "Awaiting Enlightenment" shot in this  challenge was shot at the same location. Course the rock was reversed and the clouds are gone, but it''s still the same location. Regardless of all that, it still is a fine image and I rated it at 9.<br/></td>', 'Great shot and it''s very interesting that the "Awaiting Enlightenment" shot in this  challenge was shot at the same location. Course the rock was reversed and the clouds are gone, but it''s still the same location. Regardless of all that, it still is a fine image and I rated it at 9.', '2004-06-09 22:49:13.000000', NULL, 1),
(757975, 81479, 19841, '<td valign="top">What a darling!  She''s not quite in focus, but that is offset by the good composition and fitness for the challenge.</td>', 'What a darling!  She''s not quite in focus, but that is offset by the good composition and fitness for the challenge.', '2004-06-09 22:50:35.000000', NULL, 1),
