INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(758084, 82213, 21611, '<td valign="top">great idea. had to check the title though. too bad a better angle might have included more of a draw bridge. I hemed and hawed over a six and a seven....for me the B&amp;W made it a six but I do have a prejudice against B&amp;W. so knowing this i gave it a seven :) Good luck</td>', 'great idea. had to check the title though. too bad a better angle might have included more of a draw bridge. I hemed and hawed over a six and a seven....for me the B&W made it a six but I do have a prejudice against B&W. so knowing this i gave it a seven :) Good luck', '2004-06-10 00:37:51.000000', NULL, 1),
(758085, 81578, 327, '<td valign="top">Like it! 8 from me, good tones.</td>', 'Like it! 8 from me, good tones.', '2004-06-10 00:38:16.000000', NULL, 1),
(758086, 82283, 21611, '<td valign="top">great idea. I dont think the background was important I would have filled the frame with the tombstone and the contrasting colorful flowers. nice job</td>', 'great idea. I dont think the background was important I would have filled the frame with the tombstone and the contrasting colorful flowers. nice job', '2004-06-10 00:39:54.000000', NULL, 1),
(758087, 82216, 21611, '<td valign="top">nice idea  The cart isn''t necessary the four over four would have worked better. but great shot all in all.</td>', 'nice idea  The cart isn''t necessary the four over four would have worked better. but great shot all in all.', '2004-06-10 00:42:09.000000', NULL, 1),
(758094, 82068, 16259, '<td valign="top">Impressive</td>', 'Impressive', '2004-06-10 00:48:11.000000', NULL, 1),
(758097, 81769, 16259, '<td valign="top">Picture seems to be somewhat extra vivid. A little bit if toned down colors could have produced a pleasant effect</td>', 'Picture seems to be somewhat extra vivid. A little bit if toned down colors could have produced a pleasant effect', '2004-06-10 00:49:57.000000', NULL, 1),
(758101, 81085, 16259, '<td valign="top">Excellent DOF. I somehow feel that a green crayon instead of a pencil could have added that extra touch of color.</td>', 'Excellent DOF. I somehow feel that a green crayon instead of a pencil could have added that extra touch of color.', '2004-06-10 00:54:57.000000', NULL, 1),
(758104, 82273, 16259, '<td valign="top">what is that horizontal moire on the picture? It is kind of distracting. The picture has  alot of noise in it.</td>', 'what is that horizontal moire on the picture? It is kind of distracting. The picture has  alot of noise in it.', '2004-06-10 01:00:29.000000', NULL, 1),
(758107, 81543, 16259, '<td valign="top">A sharp focus on the cell phone with low DOF could have improved the picture alot.</td>', 'A sharp focus on the cell phone with low DOF could have improved the picture alot.', '2004-06-10 01:02:54.000000', NULL, 1),
(758110, 82178, 19841, '<td valign="top">The clutter in the foreground makes it difficult to tell what''s going on here.</td>', 'The clutter in the foreground makes it difficult to tell what''s going on here.', '2004-06-10 01:12:39.000000', NULL, 1),
(758111, 82387, 7322, '<td valign="top">This looks like such a natural shot whether it''s a set-up or not. I really like the blown out area above her. I''m sure you will suffer in the voting for this but I think it adds to the mood. This was my top pick.</td>', 'This looks like such a natural shot whether it''s a set-up or not. I really like the blown out area above her. I''m sure you will suffer in the voting for this but I think it adds to the mood. This was my top pick.', '2004-06-10 01:13:53.000000', NULL, 1),
(758114, 81380, 7322, '<td valign="top">This is a really great capture of a sincere moment. The tones are beautiful</td>', 'This is a really great capture of a sincere moment. The tones are beautiful', '2004-06-10 01:14:58.000000', NULL, 1),
(758116, 82274, 7322, '<td valign="top">I really like the way this photo works; we see the foot of the person while the shadow tells the rest of the story. Nice crisp focus with good capture of highlights and good contrast on the shadow. <br/>One of my top picks.</td>', 'I really like the way this photo works; we see the foot of the person while the shadow tells the rest of the story. Nice crisp focus with good capture of highlights and good contrast on the shadow. One of my top picks.', '2004-06-10 01:16:48.000000', NULL, 1),
(758117, 81578, 7322, '<td valign="top">Thi sis a very amusing capture. The old man in the advertisement appears to be looking over the girl''s head. I like the motion blur behind her. Great job.</td>', 'Thi sis a very amusing capture. The old man in the advertisement appears to be looking over the girl''s head. I like the motion blur behind her. Great job.', '2004-06-10 01:17:41.000000', NULL, 1),
(758120, 82479, 7322, '<td valign="top">This is the best fishing shot I''ve seen in this challenge. It goes beyond the poster type image and tells the story of this man. I think part of the reason for this is the shopping cart. I really like the deep depth of field. It is a much different perspective on the fishing shot then the others used. Great job.</td>', 'This is the best fishing shot I''ve seen in this challenge. It goes beyond the poster type image and tells the story of this man. I think part of the reason for this is the shopping cart. I really like the deep depth of field. It is a much different perspective on the fishing shot then the others used. Great job.', '2004-06-10 01:19:05.000000', NULL, 1),
(758123, 82272, 7322, '<td valign="top">This is such a wonderfully expressive capture. Despite it''s technical problems (you''ve cropped a person in half and cut off a section of the main subject''s head) it is really enjoyable. One of my favorites of this challenge.</td>', 'This is such a wonderfully expressive capture. Despite it''s technical problems (you''ve cropped a person in half and cut off a section of the main subject''s head) it is really enjoyable. One of my favorites of this challenge.', '2004-06-10 01:20:51.000000', NULL, 1),
(758124, 82453, 20832, '<td valign="top">like in the movies!</td>', 'like in the movies!', '2004-06-10 01:21:21.000000', NULL, 1),
(758125, 82066, 7322, '<td valign="top">Very nice portrait. The blown out area really works as negative space.</td>', 'Very nice portrait. The blown out area really works as negative space.', '2004-06-10 01:21:45.000000', NULL, 1),
(758126, 81157, 7322, '<td valign="top">I really like the mood of this and the scope of his surroundings.</td>', 'I really like the mood of this and the scope of his surroundings.', '2004-06-10 01:22:38.000000', NULL, 1),
(758129, 82127, 7322, '<td valign="top">I think the advertisement and the guy waiting with his arms folded is what makes this. It''s all a bit blurred but I like it anyway.</td>', 'I think the advertisement and the guy waiting with his arms folded is what makes this. It''s all a bit blurred but I like it anyway.', '2004-06-10 01:24:24.000000', NULL, 1),
(758131, 81958, 20832, '<td valign="top">nice very nice but i dont see the relation with "waiting"</td>', 'nice very nice but i dont see the relation with "waiting"', '2004-06-10 01:35:35.000000', NULL, 1),
