(758988, 82288, 22892, '<td valign="top">There''s a lot of potential for this photo to annoy those who hate distractions...but I think in the end all of the lines and their distracting nature only serve to help bring out the boy more. Good job.</td>', 'There''s a lot of potential for this photo to annoy those who hate distractions...but I think in the end all of the lines and their distracting nature only serve to help bring out the boy more. Good job.', '2004-06-10 19:49:05.000000', NULL, 1),
(758992, 81760, 22892, '<td valign="top">Great idea,  the contrasting lines are bothering me a bit...you could have probably created a better effect if you composed a bit better (not saying it should necc be "not confusing," but I think it might have worked out better another way)</td>', 'Great idea,  the contrasting lines are bothering me a bit...you could have probably created a better effect if you composed a bit better (not saying it should necc be "not confusing," but I think it might have worked out better another way)', '2004-06-10 19:50:55.000000', NULL, 1),
(758993, 81706, 22892, '<td valign="top">Good photo, a bit boring however...might have worked better if there were a glimpse of what it was waiting for.</td>', 'Good photo, a bit boring however...might have worked better if there were a glimpse of what it was waiting for.', '2004-06-10 19:51:22.000000', NULL, 1),
