(759634, 82485, 19134, '<td valign="top">Okay picture. Could be brightened up a little.</td>', 'Okay picture. Could be brightened up a little.', '2004-06-11 12:50:35.000000', NULL, 1),
(759635, 82137, 19134, '<td valign="top">Hard to tell it is a fire station. The shutter being opened a little longer might have opened enough light to give a really cool effect on the lettering at the top.</td>', 'Hard to tell it is a fire station. The shutter being opened a little longer might have opened enough light to give a really cool effect on the lettering at the top.', '2004-06-11 12:53:09.000000', NULL, 1),
(759637, 82142, 19134, '<td valign="top">Great thought for a picture. A little blurry though. This is a hard shot to get clean due to the lack of lighting. Maybe if you could present more light but shorten your shutter spd. It would be a cool effect especially if you could see individual sand falling from the hand. Cool shot.</td>', 'Great thought for a picture. A little blurry though. This is a hard shot to get clean due to the lack of lighting. Maybe if you could present more light but shorten your shutter spd. It would be a cool effect especially if you could see individual sand falling from the hand. Cool shot.', '2004-06-11 12:57:07.000000', NULL, 1),
