(760123, 82066, 22046, '<td valign="top">Putting your subject to the side facing in adds a degree of suspence and tension that reinforces the idea of waiting.</td>', 'Putting your subject to the side facing in adds a degree of suspence and tension that reinforces the idea of waiting.', '2004-06-11 20:12:44.000000', NULL, 1),
(760124, 82495, 21478, '<td valign="top">This is really nice. The depth of field, colors and composition make this effective in conveying waiting. Good work!</td>', 'This is really nice. The depth of field, colors and composition make this effective in conveying waiting. Good work!', '2004-06-11 20:13:15.000000', NULL, 1),
(760125, 82191, 22046, '<td valign="top">Maybe waiting, maybe not, but a beautiful composition none the less. I rated it an 8 because it is a fine image on its own merit.</td>', 'Maybe waiting, maybe not, but a beautiful composition none the less. I rated it an 8 because it is a fine image on its own merit.', '2004-06-11 20:13:31.000000', NULL, 1),
