(760419, 82283, 9684, '<td valign="top">How wierd. My first girlfriend is a Lightfoot</td>', 'How wierd. My first girlfriend is a Lightfoot', '2004-06-12 03:02:43.000000', NULL, 1),
(760420, 81154, 9684, '<td valign="top">You must have real patience</td>', 'You must have real patience', '2004-06-12 03:04:09.000000', NULL, 1),
(760425, 82330, 9809, '<td valign="top">There certainly is a sense of anticipation here, but not a sense of waiting.</td>', 'There certainly is a sense of anticipation here, but not a sense of waiting.', '2004-06-12 03:26:02.000000', NULL, 1),
(760431, 81996, 16241, '<td valign="top">nice colours</td>', 'nice colours', '2004-06-12 04:11:02.000000', NULL, 1),
(760432, 81155, 16241, '<td valign="top">stunning  10</td>', 'stunning  10', '2004-06-12 04:11:58.000000', NULL, 1),
