(760434, 82338, 16241, '<td valign="top">very nice colours  8</td>', 'very nice colours  8', '2004-06-12 04:17:26.000000', NULL, 1),
(760438, 82266, 22011, '<td valign="top">A haircut? :-).</td>', 'A haircut? :-).', '2004-06-12 05:15:41.000000', NULL, 1),
(760439, 81690, 22011, '<td valign="top">That''s a smile that jumps out of the screen for sure...  The image seems a little soft, but it''s an interesting angle for a portrait!</td>', 'That''s a smile that jumps out of the screen for sure...  The image seems a little soft, but it''s an interesting angle for a portrait!', '2004-06-12 05:18:11.000000', NULL, 1),
(760440, 81679, 22011, '<td valign="top">This looks too dark to me, and I''m not sure what it''s really of.  The details that make it a train/bus station are not clear, and there isn''t any one person or object in clear focus or well exposed.</td>', 'This looks too dark to me, and I''m not sure what it''s really of.  The details that make it a train/bus station are not clear, and there isn''t any one person or object in clear focus or well exposed.', '2004-06-12 05:20:16.000000', NULL, 1),
(760442, 81114, 22011, '<td valign="top">The womans expression really dosn''t convey waiting.  I''m terrible with portraits so I can''t talk....</td>', 'The womans expression really dosn''t convey waiting.  I''m terrible with portraits so I can''t talk....', '2004-06-12 05:23:18.000000', NULL, 1),
(760445, 81073, 22011, '<td valign="top">Ummmm, your waiting room is on a lean, which in this case is quite distracting...</td>', 'Ummmm, your waiting room is on a lean, which in this case is quite distracting...', '2004-06-12 05:47:28.000000', NULL, 1),
(760448, 81939, 22011, '<td valign="top">This would be a great photo with out the fishing chaps, what a lovely spot...  I would have been tempted to put in more of the lake/reflection.</td>', 'This would be a great photo with out the fishing chaps, what a lovely spot...  I would have been tempted to put in more of the lake/reflection.', '2004-06-12 05:53:43.000000', NULL, 1),
(760449, 82411, 22011, '<td valign="top">I gather the wolf is waiting?  That''s a bit subtle for this time of night....  (20;54 here)</td>', 'I gather the wolf is waiting?  That''s a bit subtle for this time of night....  (20;54 here)', '2004-06-12 05:54:36.000000', NULL, 1),
(760450, 82205, 6172, '<td valign="top">sexy</td>', 'sexy', '2004-06-12 05:55:27.000000', NULL, 1),
