INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(760452, 82161, 22011, '<td valign="top">Could have been more effective in B&amp;W or sepia maybe?  The statue on the left is a stunning model...</td>', 'Could have been more effective in B&W or sepia maybe?  The statue on the left is a stunning model...', '2004-06-12 05:58:05.000000', NULL, 1),
(760453, 82441, 22011, '<td valign="top">This shot looks a bit out of focus, and your backdrop is showing it''s edge at the bottom right.  If this is a compact camera, pull back a wee bit from the subject, and crop the photo afterwards, that''ll often help the camera get a better focus.</td>', 'This shot looks a bit out of focus, and your backdrop is showing it''s edge at the bottom right.  If this is a compact camera, pull back a wee bit from the subject, and crop the photo afterwards, that''ll often help the camera get a better focus.', '2004-06-12 06:00:58.000000', NULL, 1),
(760454, 82459, 22011, '<td valign="top">Your fishing fellow seems to be a bit out of focus, but I love the ducks....</td>', 'Your fishing fellow seems to be a bit out of focus, but I love the ducks....', '2004-06-12 06:03:55.000000', NULL, 1),
(760455, 82338, 22011, '<td valign="top">This has to be california, there''s no roof on that train station.  The long shadows and back lighting make this an interesting shot.  Without the light it''d be another ''I was here'' photo.</td>', 'This has to be california, there''s no roof on that train station.  The long shadows and back lighting make this an interesting shot.  Without the light it''d be another ''I was here'' photo.', '2004-06-12 06:07:39.000000', NULL, 1),
(760456, 82383, 22011, '<td valign="top">You''ve got some odd lighting in this image, and the focus seems a little soft for a still life...</td>', 'You''ve got some odd lighting in this image, and the focus seems a little soft for a still life...', '2004-06-12 06:13:00.000000', NULL, 1),
(760462, 82119, 22011, '<td valign="top">Stunning colours..</td>', 'Stunning colours..', '2004-06-12 07:38:14.000000', NULL, 1),
(760465, 82350, 19531, '<td valign="top">Interesting.</td>', 'Interesting.', '2004-06-12 07:57:50.000000', NULL, 1),
(760473, 81726, 19531, '<td valign="top">Nice job focusing on the eyes.</td>', 'Nice job focusing on the eyes.', '2004-06-12 08:14:42.000000', NULL, 1),
(760487, 82193, 10047, '<td valign="top">A little soft on the focus. Nice frame though.</td>', 'A little soft on the focus. Nice frame though.', '2004-06-12 08:49:11.000000', NULL, 1),
(760488, 82391, 10047, '<td valign="top">Well done. Nice tone and use of light.</td>', 'Well done. Nice tone and use of light.', '2004-06-12 08:50:00.000000', NULL, 1),
(760489, 82260, 20343, '<td valign="top">Just great!</td>', 'Just great!', '2004-06-12 08:50:07.000000', NULL, 1),
(760490, 82260, 10047, '<td valign="top">Nicely done. Good use of tones and lighting.</td>', 'Nicely done. Good use of tones and lighting.', '2004-06-12 08:52:24.000000', NULL, 1),
(760492, 81912, 10047, '<td valign="top">Excellent!! Might have tried a little more contrast.</td>', 'Excellent!! Might have tried a little more contrast.', '2004-06-12 08:53:54.000000', NULL, 1),
(760493, 81787, 10047, '<td valign="top">Well done. Good texture and tone.</td>', 'Well done. Good texture and tone.', '2004-06-12 08:55:35.000000', NULL, 1),
(760495, 82487, 10047, '<td valign="top">The background is a little busy. The model really captured the expression well.</td>', 'The background is a little busy. The model really captured the expression well.', '2004-06-12 08:57:31.000000', NULL, 1),
(760497, 81823, 10047, '<td valign="top">Nice composition, texture, and tone.</td>', 'Nice composition, texture, and tone.', '2004-06-12 09:00:18.000000', NULL, 1),
(760512, 81737, 11248, '<td valign="top">Very nice picture but not sure meditation is waiting.</td>', 'Very nice picture but not sure meditation is waiting.', '2004-06-12 10:01:17.000000', NULL, 1),
(760523, 82193, 19841, '<td valign="top">I can see what you were thinking, but somehow these flowers don''t show that "boredom and anticipation" of waiting.   It is a good try, and a nice composition.</td>', 'I can see what you were thinking, but somehow these flowers don''t show that "boredom and anticipation" of waiting.   It is a good try, and a nice composition.', '2004-06-12 10:23:33.000000', NULL, 1),
(760524, 82329, 21368, '<td valign="top">Nice Shoot Groos Picture.</td>', 'Nice Shoot Groos Picture.', '2004-06-12 10:24:41.000000', NULL, 1),
(760525, 82416, 19841, '<td valign="top">Cropping off the "under new management" sign would help a lot.  Not only is it a distraction, it affects the meaning of the image.</td>', 'Cropping off the "under new management" sign would help a lot.  Not only is it a distraction, it affects the meaning of the image.', '2004-06-12 10:27:21.000000', NULL, 1),
(760527, 82388, 19841, '<td valign="top">You really caught her expression well.</td>', 'You really caught her expression well.', '2004-06-12 10:33:03.000000', NULL, 1),
(760529, 81786, 19841, '<td valign="top">This only conveys the sense of "waiting" if you prefer open blossoms.  If you prefer buds, the concept is not there.</td>', 'This only conveys the sense of "waiting" if you prefer open blossoms.  If you prefer buds, the concept is not there.', '2004-06-12 10:35:13.000000', NULL, 1),
(760530, 82174, 19841, '<td valign="top">I like the informal setting, it looks cozy on the livingroom rug.</td>', 'I like the informal setting, it looks cozy on the livingroom rug.', '2004-06-12 10:38:33.000000', NULL, 1),
(760532, 82346, 15920, '<td valign="top">Good choice for the challenge, but a dreary day with lots of wet pavement makes a tough job of making a great photo.  You did well, but, the road that curves in on the bottom doesn''t help.  I wonder if you could have cropped this a bit differently to get in toghter on the people waiting.  Just a thought.</td>', 'Good choice for the challenge, but a dreary day with lots of wet pavement makes a tough job of making a great photo.  You did well, but, the road that curves in on the bottom doesn''t help.  I wonder if you could have cropped this a bit differently to get in toghter on the people waiting.  Just a thought.', '2004-06-12 10:49:40.000000', NULL, 1),
(760558, 81741, 15920, '<td valign="top">Bigger would have been better, but I agree with the idea.  -8</td>', 'Bigger would have been better, but I agree with the idea.  -8', '2004-06-12 11:16:39.000000', NULL, 1),
(760560, 82440, 15920, '<td valign="top">Bigger would have been better, but the "watched pot never boils" idea is clear.  That spot of grass is a bit distracting, but not bad.</td>', 'Bigger would have been better, but the "watched pot never boils" idea is clear.  That spot of grass is a bit distracting, but not bad.', '2004-06-12 11:17:50.000000', NULL, 1),
(760565, 82182, 15920, '<td valign="top">Great photo, but, it looks more like thinking deeply than waiting.  Sky is perfect and the border works.</td>', 'Great photo, but, it looks more like thinking deeply than waiting.  Sky is perfect and the border works.', '2004-06-12 11:20:09.000000', NULL, 1),
(760571, 81955, 15920, '<td valign="top">I think this photo is well done, but, she looks more like she is trying stay dry rather than wait out the rain.  I would have entered it in the open challenge, because this is a very well taken portrait.</td>', 'I think this photo is well done, but, she looks more like she is trying stay dry rather than wait out the rain.  I would have entered it in the open challenge, because this is a very well taken portrait.', '2004-06-12 11:31:47.000000', NULL, 1),
(760578, 81659, 15920, '<td valign="top">The mirrow really makes this shot.  The liighting could be better, as you lost a little detail on the arm, but, a good job overall.</td>', 'The mirrow really makes this shot.  The liighting could be better, as you lost a little detail on the arm, but, a good job overall.', '2004-06-12 11:45:39.000000', NULL, 1),
(760579, 82052, 15920, '<td valign="top">Most people will not understand this.  Good luck.</td>', 'Most people will not understand this.  Good luck.', '2004-06-12 11:46:46.000000', NULL, 1),
(760582, 82460, 15920, '<td valign="top">Looks just a little staged, but, it does capture a little talked about part of the tourism experience.</td>', 'Looks just a little staged, but, it does capture a little talked about part of the tourism experience.', '2004-06-12 11:49:41.000000', NULL, 1),
(760586, 82299, 15920, '<td valign="top">This would be a forgetable picture without the fence.  Your POV choice is great.  By not looking through the opening of the fence, but forcing the viewto look around it, you creat a cool effect.</td>', 'This would be a forgetable picture without the fence.  Your POV choice is great.  By not looking through the opening of the fence, but forcing the viewto look around it, you creat a cool effect.', '2004-06-12 11:51:49.000000', NULL, 1),
(760592, 81675, 15920, '<td valign="top">This composition makes a good photo, but doesn''t really communicate waiting.  If there was a camera or telescope, or something else that they were waiting to use, I might sense waiting.  That aside, I do really like this.  All the lines that cross in interesting ways, the colors, and the look of concentration on the model all work really well together.</td>', 'This composition makes a good photo, but doesn''t really communicate waiting.  If there was a camera or telescope, or something else that they were waiting to use, I might sense waiting.  That aside, I do really like this.  All the lines that cross in interesting ways, the colors, and the look of concentration on the model all work really well together.', '2004-06-12 11:56:43.000000', NULL, 1),
(760594, 82205, 15920, '<td valign="top">Nicely done, but, the sepia tones weren''t necessary.</td>', 'Nicely done, but, the sepia tones weren''t necessary.', '2004-06-12 11:59:42.000000', NULL, 1),
(760599, 81787, 15920, '<td valign="top">Dark subject, but it hammers the challenge.  Great idea.  One suggestion: make the shadows from the bars sharper and starker. -8</td>', 'Dark subject, but it hammers the challenge.  Great idea.  One suggestion: make the shadows from the bars sharper and starker. -8', '2004-06-12 12:05:10.000000', NULL, 1),
(760605, 82391, 8522, '<td valign="top">Shame it''s overexposed... although there is quite a bit of highlight detail you could have rescued using curves.</td>', 'Shame it''s overexposed... although there is quite a bit of highlight detail you could have rescued using curves.', '2004-06-12 12:11:23.000000', NULL, 1),
(760607, 81731, 8522, '<td valign="top">Superb picture, but doesn''t give me a feeling of waiting.</td>', 'Superb picture, but doesn''t give me a feeling of waiting.', '2004-06-12 12:11:54.000000', NULL, 1),
(760608, 82399, 15920, '<td valign="top">Good idea, but looks a little staged.</td>', 'Good idea, but looks a little staged.', '2004-06-12 12:13:09.000000', NULL, 1),
(760613, 82102, 8522, '<td valign="top">I don''t get this.</td>', 'I don''t get this.', '2004-06-12 12:19:23.000000', NULL, 1),
(760614, 81152, 15920, '<td valign="top">I think this would have been great without the blue cast.  It is one of the clearly staged entries in teh challenge that looks natural, but the color hurts the mood.</td>', 'I think this would have been great without the blue cast.  It is one of the clearly staged entries in teh challenge that looks natural, but the color hurts the mood.', '2004-06-12 12:20:43.000000', NULL, 1),
(760617, 82350, 8522, '<td valign="top">Good dof. Terrible jpeg artifacting, use less compression next time.</td>', 'Good dof. Terrible jpeg artifacting, use less compression next time.', '2004-06-12 12:21:57.000000', NULL, 1),
(760621, 82318, 15920, '<td valign="top">Bigger would have been better, but this is very good for the challenge.</td>', 'Bigger would have been better, but this is very good for the challenge.', '2004-06-12 12:23:53.000000', NULL, 1),
(760625, 82141, 15920, '<td valign="top">Great portrait, but, she looks content in the rain.  Why not save this for the open challenge, as it is much better as simply a good picture than something depicting waiting?</td>', 'Great portrait, but, she looks content in the rain.  Why not save this for the open challenge, as it is much better as simply a good picture than something depicting waiting?', '2004-06-12 12:27:00.000000', NULL, 1),
(760627, 82409, 15920, '<td valign="top">Well done desat, but waiting?</td>', 'Well done desat, but waiting?', '2004-06-12 12:37:31.000000', NULL, 1),
(760633, 82145, 14438, '<td valign="top">Challenge not met. I understand another expression than "waiting": hungry !</td>', 'Challenge not met. I understand another expression than "waiting": hungry !', '2004-06-12 12:42:39.000000', NULL, 1),
(760639, 82159, 20960, '<td valign="top">10 for your optermism................</td>', '10 for your optermism................', '2004-06-12 12:47:59.000000', NULL, 1),
(760649, 81049, 22680, '<td valign="top">Nice one</td>', 'Nice one', '2004-06-12 13:08:05.000000', NULL, 1),
(760657, 82480, 15920, '<td valign="top">Perfect DOF, but it looks a little staged.</td>', 'Perfect DOF, but it looks a little staged.', '2004-06-12 13:24:59.000000', NULL, 1),
(760660, 81652, 22166, '<td valign="top">Hope every one "sees" this. And I hope no one "disses" on the flame being off center and no ripples in the water... Why not let this great shot stand alone?</td>', 'Hope every one "sees" this. And I hope no one "disses" on the flame being off center and no ripples in the water... Why not let this great shot stand alone?', '2004-06-12 13:31:12.000000', NULL, 1),
(760663, 82137, 15920, '<td valign="top">This is a great night shot.  But, it doesn''t make me feel like I am watching waiting.  Why not hold this for the open challenge?</td>', 'This is a great night shot.  But, it doesn''t make me feel like I am watching waiting.  Why not hold this for the open challenge?', '2004-06-12 13:34:41.000000', NULL, 1),
(760667, 82286, 15920, '<td valign="top">Good idea, but why desat?  This would have been great as you saw it naturally.</td>', 'Good idea, but why desat?  This would have been great as you saw it naturally.', '2004-06-12 13:36:51.000000', NULL, 1),
(760668, 81478, 18639, '<td valign="top">to much hue on it. collors look unreal</td>', 'to much hue on it. collors look unreal', '2004-06-12 13:36:53.000000', NULL, 1),
(760671, 81313, 22166, '<td valign="top">Don''t know about anyone else, but as "cheery" as they try to make these places, bored is bored.</td>', 'Don''t know about anyone else, but as "cheery" as they try to make these places, bored is bored.', '2004-06-12 13:42:33.000000', NULL, 1),
(760672, 82177, 22166, '<td valign="top">They pace, they look.  They pace and look then lay down and sigh....</td>', 'They pace, they look.  They pace and look then lay down and sigh....', '2004-06-12 13:45:49.000000', NULL, 1),
(760701, 82485, 10047, '<td valign="top">I''ve seen that look before. Nicely done. Maybe a little dark.</td>', 'I''ve seen that look before. Nicely done. Maybe a little dark.', '2004-06-12 14:34:53.000000', NULL, 1),
(760702, 81718, 10047, '<td valign="top">That brings back memories! Nicely done. Maybe a tad soft on the focus.</td>', 'That brings back memories! Nicely done. Maybe a tad soft on the focus.', '2004-06-12 14:35:50.000000', NULL, 1),
(760704, 81313, 10047, '<td valign="top">Seems a bit washed out, but the red adds some good contrast.</td>', 'Seems a bit washed out, but the red adds some good contrast.', '2004-06-12 14:36:49.000000', NULL, 1),
(760706, 82161, 10047, '<td valign="top">A tad soft, but nice composition.</td>', 'A tad soft, but nice composition.', '2004-06-12 14:37:40.000000', NULL, 1),
(760707, 82289, 10047, '<td valign="top">Seems to have a green cast.</td>', 'Seems to have a green cast.', '2004-06-12 14:38:37.000000', NULL, 1),
(760710, 82330, 10047, '<td valign="top">A little washed out at the bottom, but good use of b&amp;w.</td>', 'A little washed out at the bottom, but good use of b&w.', '2004-06-12 14:40:38.000000', NULL, 1),
(760711, 82463, 10047, '<td valign="top">Nice color combo (blues and tans).</td>', 'Nice color combo (blues and tans).', '2004-06-12 14:42:27.000000', NULL, 1),
(760713, 81972, 10047, '<td valign="top">Maybe a tad soft, and there seems to be some jaggies aroud the t-shirt edges. I might have cropped it a little tighter on the right. Creative.</td>', 'Maybe a tad soft, and there seems to be some jaggies aroud the t-shirt edges. I might have cropped it a little tighter on the right. Creative.', '2004-06-12 14:44:39.000000', NULL, 1),
(760714, 81741, 10047, '<td valign="top">A little on the small side. Also a lot of pink and blue coloring.</td>', 'A little on the small side. Also a lot of pink and blue coloring.', '2004-06-12 14:46:48.000000', NULL, 1),
(760716, 82449, 10047, '<td valign="top">The bird is a little washed out. Nice composition and reflection.</td>', 'The bird is a little washed out. Nice composition and reflection.', '2004-06-12 14:48:12.000000', NULL, 1),
(760718, 82254, 10047, '<td valign="top">Beautiful. Well done. Can''t decide if the person adds or detracts.</td>', 'Beautiful. Well done. Can''t decide if the person adds or detracts.', '2004-06-12 14:49:11.000000', NULL, 1),
(760723, 82147, 10047, '<td valign="top">Looks like Killdeer eggs. I was checking a nest each day, but the eggs disappeared one night. Nicely done and good composition.</td>', 'Looks like Killdeer eggs. I was checking a nest each day, but the eggs disappeared one night. Nicely done and good composition.', '2004-06-12 14:51:07.000000', NULL, 1),
(760727, 82405, 10047, '<td valign="top">I might have tried for a tighter crop.</td>', 'I might have tried for a tighter crop.', '2004-06-12 14:53:25.000000', NULL, 1),
(760728, 81948, 10047, '<td valign="top">Nice color and contrast.</td>', 'Nice color and contrast.', '2004-06-12 14:54:08.000000', NULL, 1),
(760729, 82348, 10047, '<td valign="top">Funny! I might have tried cropping out the overexposure on the left.</td>', 'Funny! I might have tried cropping out the overexposure on the left.', '2004-06-12 14:55:12.000000', NULL, 1),
(760730, 82423, 10047, '<td valign="top">Cute. Nice use of B&amp;W.</td>', 'Cute. Nice use of B&W.', '2004-06-12 14:56:13.000000', NULL, 1),
(760733, 82417, 10047, '<td valign="top">Excellent capture. Great expression. I might have tried for more contrast while editing, but I really like this photo.</td>', 'Excellent capture. Great expression. I might have tried for more contrast while editing, but I really like this photo.', '2004-06-12 14:57:55.000000', NULL, 1),
(760734, 81154, 10047, '<td valign="top">Cute, maybe a little soft.</td>', 'Cute, maybe a little soft.', '2004-06-12 14:58:26.000000', NULL, 1),
(760735, 82292, 10047, '<td valign="top">A little soft. I might have tried croipping further to the left.</td>', 'A little soft. I might have tried croipping further to the left.', '2004-06-12 14:59:29.000000', NULL, 1),
(760798, 82362, 2716, '<td valign="top">Great silhouette.  I like Awaiting Enlightenment too.  NIce shot.  Jacko.</td>', 'Great silhouette.  I like Awaiting Enlightenment too.  NIce shot.  Jacko.', '2004-06-12 17:08:04.000000', NULL, 1),
(760802, 82452, 18757, '<td valign="top">it is a nice picture. i like the header and concept...</td>', 'it is a nice picture. i like the header and concept...', '2004-06-12 17:17:11.000000', NULL, 1),
(760808, 81732, 18757, '<td valign="top">i dont understand what is the relation. I have seen clouds million times in the sky similar to them but i have never live a storm after seeing them...</td>', 'i dont understand what is the relation. I have seen clouds million times in the sky similar to them but i have never live a storm after seeing them...', '2004-06-12 17:21:20.000000', NULL, 1),
(760809, 81547, 18757, '<td valign="top">nice dof.is it live?</td>', 'nice dof.is it live?', '2004-06-12 17:22:46.000000', NULL, 1),
(760818, 81763, 10818, '<td valign="top">Very soft picture, pretty photo.</td>', 'Very soft picture, pretty photo.', '2004-06-12 17:38:05.000000', NULL, 1),
