(764736, 81152, 11738, '<td valign="top">Blue flamed candles, huh?  Doesn''t quite cut it.  Should have gone with yellow/orange tone, sepia or black and white.</td>', 'Blue flamed candles, huh?  Doesn''t quite cut it.  Should have gone with yellow/orange tone, sepia or black and white.', '2004-06-15 23:50:11.000000', NULL, 1),
(764742, 81499, 20771, '<td valign="top">The flower is arresting, and the flower closeup is terrific, but I find  the slant of the horizon and the nonvertical house and trees in the background are distracting.</td>', 'The flower is arresting, and the flower closeup is terrific, but I find  the slant of the horizon and the nonvertical house and trees in the background are distracting.', '2004-06-15 23:56:15.000000', NULL, 1),
